  1988	      && fencedSnapshot.providerIdentity === null
  1989	      && fencedSnapshot.workerPid !== null
  1990	      && pidAlive(fencedSnapshot.workerPid)
  1991	      && now - Date.parse(cancel.requestedAt) < MANAGED_HOST_RUN_PREIDENTITY_RECOVERY_GRACE_MS) return;
