    76	function corruptSlotIdentity(file: string, raw: string): string {
    77	  try {
    78	    const stat = statSync(file);
    79	    return `${stat.dev}:${stat.ino}:${stat.size}:${stat.mtimeMs}:${raw}`;
    80	  } catch (error) {
    81	    return `unstatable:${(error as NodeJS.ErrnoException).code ?? 'unknown'}:${raw}`;
    82	  }
    83	}
    84	
    85	function ownString(value: Record<string, unknown>, key: string): string | null {
    86	  if (!Object.prototype.hasOwnProperty.call(value, key)) return null;
    87	  return typeof value[key] === 'string' ? value[key] as string : null;
    88	}
    89	
    90	function ownNumber(value: Record<string, unknown>, key: string): number | null {
    91	  if (!Object.prototype.hasOwnProperty.call(value, key)) return null;
    92	  return typeof value[key] === 'number' && Number.isInteger(value[key]) ? value[key] as number : null;
    93	}
