    95	function readSlotOccupant(file: string): SlotOccupant {
    96	  let raw: string;
    97	  try {
    98	    raw = readFileSync(file, 'utf8');
    99	  } catch (error) {
   100	    return (error as NodeJS.ErrnoException).code === 'ENOENT'
   101	      ? { state: 'missing' }
   102	      : { state: 'corrupt', identity: corruptSlotIdentity(file, '') };
   103	  }
   104	  try {
   105	    const parsed = JSON.parse(raw) as unknown;
   106	    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
   107	      return { state: 'corrupt', identity: corruptSlotIdentity(file, raw) };
   108	    }
   109	    const meta = parsed as Record<string, unknown>;
   110	    const pid = ownNumber(meta, 'pid');
   111	    if (pid === null) return { state: 'corrupt', identity: corruptSlotIdentity(file, raw) };
   112	    return { state: 'valid', pid, token: ownString(meta, 'token'), meta };
   113	  } catch {
   114	    return { state: 'corrupt', identity: corruptSlotIdentity(file, raw) };
   115	  }
   116	}
