   118	function sameSlotOccupant(left: SlotOccupant, right: SlotOccupant): boolean {
   119	  if (left.state !== right.state) return false;
   120	  if (left.state === 'valid' && right.state === 'valid') {
   121	    return left.pid === right.pid && left.token === right.token;
   122	  }
   123	  if (left.state === 'corrupt' && right.state === 'corrupt') {
   124	    return left.identity === right.identity;
   125	  }
   126	  return true;
   127	}
