   129	function pidAlive(pid: number): boolean {
   130	  if (!Number.isInteger(pid) || pid <= 0) return false;
   131	  try {
   132	    process.kill(pid, 0);
   133	    return true;
   134	  } catch (error) {
   135	    return (error as NodeJS.ErrnoException).code === 'EPERM';
   136	  }
   137	}
   138	
   139	function processGroupAlive(pgid: number): boolean {
   140	  if (!Number.isInteger(pgid) || pgid <= 0 || process.platform === 'win32') return false;
   141	  try {
   142	    process.kill(-pgid, 0);
   143	    return true;
   144	  } catch (error) {
   145	    return (error as NodeJS.ErrnoException).code === 'EPERM';
   146	  }
   147	}
