   149	function slotReclaimable(occupant: SlotOccupant, file: string, now: number, staleMs: number): boolean {
   150	  if (occupant.state === 'missing') return true;
   151	  if (occupant.state === 'valid') {
   152	    const isolated = occupant.meta.providerProcessGroupIsolated === true;
   153	    const providerPgid = ownNumber(occupant.meta, 'providerPgid');
