   202	function scanLiveProviderProcessSlotsUnlocked(
   203	  dir: string,
   204	  now: number,
   205	  staleMs: number,
   206	): ProviderProcessLiveDescriptor[] {
   207	  let entries: string[];
   208	  try {
   209	    entries = readdirSync(dir);
   210	  } catch (error) {
   211	    if ((error as NodeJS.ErrnoException).code === 'ENOENT') return [];
   212	    const code = (error as NodeJS.ErrnoException).code ?? 'unknown';
   213	    const detail = error instanceof Error ? error.message : String(error);
   214	    throw new Error(`provider-process-registry slots directory unreadable (${code}): ${detail}`);
   215	  }
   216	  const live: ProviderProcessLiveDescriptor[] = [];
   217	  for (const name of entries) {
   218	    if (!name.endsWith('.json')) continue;
   219	    const file = join(dir, name);
   220	    const occupant = readSlotOccupant(file);
   221	    if (slotReclaimable(occupant, file, now, staleMs)) {
   222	      if (occupant.state !== 'missing' && sameSlotOccupant(readSlotOccupant(file), occupant)) {
   223	        try { unlinkSync(file); } catch { /* racing reclaim is benign */ }
   224	      }
   225	      continue;
   226	    }
   227	    if (occupant.state !== 'valid') continue;
   228	    live.push({
   229	      pid: occupant.pid,
   230	      startedAt: ownString(occupant.meta, 'startedAt') ?? '',
   231	      host: ownString(occupant.meta, 'host') ?? '',
   232	      storyId: ownString(occupant.meta, 'storyId'),
   233	      agentType: ownString(occupant.meta, 'agentType') ?? '',
   234	    });
   235	  }
   236	  return live;
   237	}
