   378	  lockTiming: ProviderRegistryLockTiming = {},
   379	  mutationOps: ProviderRegistryMutationOps = DEFAULT_PROVIDER_REGISTRY_MUTATION_OPS,
   380	): void {
   381	  try {
   382	    releaseProviderProcessSlot(file, token, lockTiming, mutationOps);
   383	  } catch (error) {
   384	    // Never rethrow: this runs in finally. Reporting must not fail either.
   385	    try {
   386	      onFailure(error);
   387	    } catch { /* a broken reporter must not mask the caller's exception */ }
   388	  }
   389	}
