   463	export function isProviderExecutionSurfaceCandidate(relativePath: string, source: string): boolean {
   464	  if (!relativePath.endsWith('.ts')) return false;
   465	  if (/(?:^|\/)(?:tasks|tests|generated)(?:\/|$)/.test(relativePath)) return false;
   466	  if (relativePath === 'core/provider-process-registry.ts') return false;
   467	  if (/^providers\/(?:codex-cli|claude-cli|gemini-cli)\.ts$/.test(relativePath)) return true;
   468	  if (/providers\/(?:codex-cli|claude-cli|gemini-cli)\.js/.test(source)) return true;
   469	  if (/\brunHostRun\s*\(/.test(source)) return true;
   470	  // B-137a: strip documentation filename references before the provider-word
   471	  // scan. The words are matched case-insensitively, so a prose citation of
   472	  // "CLAUDE.md" (the project convention doc, referenced by many core modules)
   473	  // read as a provider reference: any file that both used child_process for git
   474	  // and cited that doc became an "unclassified provider execution surface".
   475	  // scope-contract.ts tripped exactly this way on a comment citing the handler
   476	  // convention -- a docs citation, not a provider workload. Several already
   477	  // inventoried files (audit-scan, audit-trigger, rollout-check,
   478	  // runtime-environment-checks) match for the same non-reason. Stripping only
   479	  // "<provider>.md" filenames keeps every real provider reference intact,
   480	  // including CLAUDE_CLI, claudeCli, 'claude' and providers/claude-cli.js.
   481	  const withoutDocReferences = source.replace(/\b(?:codex|claude|agy|gemini|antigravity)\.md\b/gi, '');
   482	  // B-137a: the provider word no longer requires a trailing \b. The old
   483	  // /\bclaude\b/i missed identifier forms entirely -- `claudeCli`, `CLAUDE_CLI`,
   484	  // `codexRunner` all failed to match, because \b does not break between two
