   263	async function eventually(predicate: () => Promise<boolean>, message: string, timeoutMs = 10_000): Promise<void> {
   264	  const deadline = Date.now() + timeoutMs;
   265	  while (Date.now() < deadline) {
   266	    if (await predicate()) return;
   267	    await new Promise(resolve => setTimeout(resolve, 10));
   268	  }
   269	  throw new Error(message);
